import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering by role, username pattern."""
    role_filter = request.args.get('role', '')
    username_pattern = request.args.get('q', '')
    page = request.args.get('page', '1')

    # Input length validation
    if len(username_pattern) > 100:
        return jsonify({'error': 'Query too long'}), 400

    # Basic character check - allow alphanumeric, spaces, and common chars
    # Note: this is NOT a security boundary, just UX validation
    db = get_db()

    # Build query with filters
    base_query = "SELECT id, username, email, role FROM users WHERE 1=1"

    if role_filter:
        base_query += f" AND role = '{role_filter}'"

    if username_pattern:
        base_query += f" AND username LIKE '%{username_pattern}%'"

    base_query += f" LIMIT 20 OFFSET {(int(page) - 1) * 20}"

    try:
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search for compliance
        db.execute(
            "INSERT INTO audit_log (action, details) VALUES (?, ?)",
            ('user_search', f'role={role_filter}, q={username_pattern}')
        )
        db.commit()

        return jsonify({'users': results, 'page': int(page)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'email', 'password')):
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)",
            (data['username'], data['email'], password_hash)
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
